-- ============================================================================
-- Remove stale description_json validation errors generated by the old
-- ProductDraftBuilder bug that sent JSON UTF-8 bytes to Product Service where
-- ProductDescription protobuf bytes were required.
--
-- This is a narrow data repair:
--   - only VALIDATE_PRODUCT_DRAFT rows
--   - only description_json / DESC_BLOCK_INVALID
--   - only the old protobuf parser message prefix
-- Then recalculate affected items' blocking_error_count from remaining ERROR rows.
-- ============================================================================

WITH deleted AS (
    DELETE FROM product_import_item_error
    WHERE source = 'VALIDATE_PRODUCT_DRAFT'
      AND field = 'description_json'
      AND error_type = 'DESC_BLOCK_INVALID'
      AND message LIKE 'description_json 解析失敗：Protocol message%'
    RETURNING import_item_id
),
affected_items AS (
    SELECT DISTINCT import_item_id
    FROM deleted
    WHERE import_item_id IS NOT NULL
)
UPDATE product_import_item pii
SET blocking_error_count = (
        SELECT COUNT(*)
        FROM product_import_item_error piie
        WHERE piie.import_item_id = pii.id
          AND piie.severity = 'ERROR'
    ),
    updated_at = NOW()
WHERE pii.id IN (SELECT import_item_id FROM affected_items);
